#!/bin/bash
# Generated by Claude Code — archiviert die App (Release), signiert sie für
# den App Store und lädt sie zu App Store Connect / TestFlight hoch.
#
# Erwartet ~/.appstoreconnect/config mit:
#   ASC_KEY_ID=XXXXXXXXXX
#   ASC_ISSUER_ID=xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx
#   ASC_KEY_PATH=$HOME/.appstoreconnect/AuthKey_XXXXXXXXXX.p8
# Die .p8-Datei bleibt lokal und wird nie eingecheckt.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
cd "$SCRIPT_DIR"
TEAM_ID="DVH3MYQ64A"
CONFIG="$HOME/.appstoreconnect/config"
[ -f "$CONFIG" ] || { echo "❌ $CONFIG fehlt (ASC_KEY_ID, ASC_ISSUER_ID, ASC_KEY_PATH)."; exit 1; }
# shellcheck disable=SC1090
source "$CONFIG"
[ -f "$ASC_KEY_PATH" ] || { echo "❌ API-Schlüssel nicht gefunden: $ASC_KEY_PATH"; exit 1; }
[ -f Config/Secrets.plist ] || { echo "❌ Config/Secrets.plist fehlt — ohne Supabase-Konfiguration kein Upload."; exit 1; }

# Gemeinsamer Zähler mit deploy-iphone.sh: jede hochgeladene Build-Nummer
# muss eindeutig und steigend sein.
COUNTER="$HOME/.klangradar-build-number"
BUILD_NUMBER=$(( $(cat "$COUNTER" 2>/dev/null || echo 722) + 1 ))
VERSION="$((BUILD_NUMBER / 100)).$(((BUILD_NUMBER / 10) % 10)).$((BUILD_NUMBER % 10))"
WORK="/tmp/KlangradarTestFlight"
rm -rf "$WORK"; mkdir -p "$WORK"
AUTH=(-allowProvisioningUpdates -authenticationKeyPath "$ASC_KEY_PATH" -authenticationKeyID "$ASC_KEY_ID" -authenticationKeyIssuerID "$ASC_ISSUER_ID")

if [ "${SKIP_UI_TESTS:-0}" != "1" ]; then
  echo "🧪 UI-Tests …"
  ./run-ui-tests.sh || { echo "❌ Upload abgebrochen: UI-Tests fehlgeschlagen (SKIP_UI_TESTS=1 überspringt)"; exit 1; }
fi

echo "📦 Archiviere Version $VERSION (Build $BUILD_NUMBER) …"
xcodebuild archive \
  -project KlangradarNative.xcodeproj -scheme KlangradarNative -configuration Release \
  -destination "generic/platform=iOS" -archivePath "$WORK/Klangradar.xcarchive" \
  DEVELOPMENT_TEAM="$TEAM_ID" CURRENT_PROJECT_VERSION="$BUILD_NUMBER" MARKETING_VERSION="$VERSION" \
  "${AUTH[@]}" > "$WORK/archive.log" 2>&1 || { grep -E "error:" "$WORK/archive.log" | head -20; echo "❌ Archivieren fehlgeschlagen ($WORK/archive.log)"; exit 1; }

cat > "$WORK/ExportOptions.plist" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>method</key><string>app-store-connect</string>
  <key>destination</key><string>upload</string>
  <key>teamID</key><string>$TEAM_ID</string>
  <key>signingStyle</key><string>automatic</string>
  <key>manageAppVersionAndBuildNumber</key><false/>
  <key>uploadSymbols</key><true/>
</dict></plist>
PLIST

echo "☁️  Lade zu App Store Connect hoch …"
xcodebuild -exportArchive -archivePath "$WORK/Klangradar.xcarchive" -exportOptionsPlist "$WORK/ExportOptions.plist" \
  -exportPath "$WORK/export" "${AUTH[@]}" > "$WORK/export.log" 2>&1 || { grep -E "error|Error" "$WORK/export.log" | head -20; echo "❌ Upload fehlgeschlagen ($WORK/export.log)"; exit 1; }

echo "$BUILD_NUMBER" > "$COUNTER"
echo "✅ Hochgeladen: Version $VERSION (Build $BUILD_NUMBER). In 10–30 Min. unter TestFlight sichtbar."

# Testhinweis ("Was testen?") aus KlangradarNative/Resources/WhatsNew.json –
# im Hintergrund, weil App Store Connect den Build erst nach einigen Minuten
# kennt. Script und Notizen vorher kopieren: der Worktree wird beim nächsten
# Lauf neu angelegt.
NOTES_DIR="$HOME/.klangradar-whatsnew"
rm -rf "$NOTES_DIR"; mkdir -p "$NOTES_DIR/Scripts" "$NOTES_DIR/KlangradarNative/Resources"
cp Scripts/testflight_whats_new.rb "$NOTES_DIR/Scripts/"
cp KlangradarNative/Resources/WhatsNew.json "$NOTES_DIR/KlangradarNative/Resources/"
nohup ruby "$NOTES_DIR/Scripts/testflight_whats_new.rb" "$BUILD_NUMBER" > /tmp/klangradar-whatsnew.log 2>&1 &
echo "📝 TestFlight-Testhinweis wird gesetzt, sobald der Build verarbeitet ist (/tmp/klangradar-whatsnew.log)."
